fn append_detected_llm_presets(presets: &mut Vec<Value>, detected: &[Value]) {
    for endpoint in detected {
        if endpoint["openaiCompatible"] != Value::Bool(true) {
            continue;
        }
        let label = endpoint["label"].as_str().unwrap_or("backend");
        presets.push(json!({
            "id": format!("use-detected-{label}"),
            "summary": format!("Use the detected {label} OpenAI-compatible backend"),
            "description": "Apply a selected detected endpoint and one of its advertised models to a required tier.",
            "requiresInstall": false,
            "endpoint": endpoint["endpoint"],
            "models": endpoint["models"],
            "nextSteps": ["select a tier and detected model", "apply the preset", "run doctor"]
        }));
    }
}

fn required_llm_tiers_missing(root: &Path) -> Result<BTreeSet<ProjectLlmTier>, ToolError> {
    let mut missing = BTreeSet::new();
    for tier in [ProjectLlmTier::Embedding] {
        if load_project_llm_tier(root, tier)
            .map_err(project_llm_error)?
            .is_none()
        {
            missing.insert(tier);
        }
    }
    Ok(missing)
}

fn uses_recommended_local_models(configured: &[Value], directory: &Path) -> bool {
    configured.iter().any(|tier| {
        let Some(model) = tier["model"].as_str() else {
            return false;
        };
        let model = Path::new(model);
        model.extension().and_then(|value| value.to_str()) == Some("gguf")
            && model.parent() == Some(directory)
    })
}

fn optional_bounded_admin_u64(
    arguments: &Map<String, Value>,
    key: &str,
    maximum: u64,
) -> Result<Option<u64>, ToolError> {
    optional_u64(arguments, key)?.map_or(Ok(None), |value| {
        (1..=maximum)
            .contains(&value)
            .then_some(Some(value))
            .ok_or_else(invalid_arguments)
    })
}

fn optional_bounded_admin_u16(
    arguments: &Map<String, Value>,
    key: &str,
    maximum: u16,
) -> Result<Option<u16>, ToolError> {
    optional_bounded_admin_u64(arguments, key, u64::from(maximum))?
        .map(|value| u16::try_from(value).map_err(|_| invalid_arguments()))
        .transpose()
}

fn parse_summary_sweep_limit(
    arguments: &Map<String, Value>,
) -> Result<SummarySweepLimit, ToolError> {
    if arguments.contains_key("limit") && arguments.contains_key("summarizeLimit") {
        return Err(safe_error(
            ToolErrorCode::InvalidArguments,
            "summarize accepts either summarizeLimit or the v2 limit alias, not both",
        ));
    }
    let value = arguments
        .get("summarizeLimit")
        .or_else(|| arguments.get("limit"));
    match value {
        None => Ok(SummarySweepLimit::Bounded(SUMMARY_DEFAULT_SWEEP_LIMIT)),
        Some(Value::Number(value)) => value
            .as_f64()
            .filter(|value| value.is_finite())
            .ok_or_else(invalid_arguments)
            .and_then(|value| {
                if value < 0.0 {
                    return Ok(SummarySweepLimit::Uncapped);
                }
                if value
                    > SUMMARY_MAXIMUM_SWEEP_LIMIT
                        .to_f64()
                        .ok_or_else(invalid_arguments)?
                {
                    return Err(invalid_arguments());
                }
                value
                    .ceil()
                    .to_u64()
                    .map(SummarySweepLimit::Bounded)
                    .ok_or_else(invalid_arguments)
            }),
        Some(_) => Err(invalid_arguments()),
    }
}

fn configured_summary_limit(limit: ProjectSummaryEagerLimit) -> SummarySweepLimit {
    match limit {
        ProjectSummaryEagerLimit::Bounded(limit) => SummarySweepLimit::Bounded(limit),
        ProjectSummaryEagerLimit::Uncapped => SummarySweepLimit::Uncapped,
    }
}

fn project_summary_policy(project_root: &Path) -> Result<SummaryCandidatePolicy, ToolError> {
    let settings = load_project_summary_settings(project_root).map_err(project_llm_error)?;
    SummaryCandidatePolicy::new(
        settings.minimum_body_lines(),
        settings.minimum_body_lines_by_kind().clone(),
    )
    .map_err(internal_error)
}

fn parse_admin_max_file_size(arguments: &Map<String, Value>) -> Result<Option<usize>, ToolError> {
    optional_bounded_text(arguments, "maxFileSize", 32)?
        .map(crate::parse_max_file_size)
        .transpose()
        .map_err(|_| invalid_arguments())
}

struct PreparedAdminProjectRoot {
    root: PathBuf,
    state_directory_created: bool,
}

fn prepare_admin_project_root(
    requested: Option<&str>,
    current_root: &Path,
) -> Result<PreparedAdminProjectRoot, ToolError> {
    let requested_path = requested.map_or_else(|| current_root.to_path_buf(), PathBuf::from);
    if !requested_path.is_absolute() {
        return Err(safe_error(
            ToolErrorCode::InvalidArguments,
            "admin init/uninit path must be absolute",
        ));
    }
    match std::fs::symlink_metadata(&requested_path) {
        Ok(metadata) if metadata.file_type().is_symlink() || !metadata.is_dir() => {
            return Err(safe_error(
                ToolErrorCode::InvalidArguments,
                "admin project path must be a real directory, not a symlink",
            ));
        }
        Ok(_) => {}
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            std::fs::create_dir_all(&requested_path).map_err(|_| {
                safe_error(
                    ToolErrorCode::Unavailable,
                    "admin project directory could not be created",
                )
            })?;
        }
        Err(_) => {
            return Err(safe_error(
                ToolErrorCode::Unavailable,
                "admin project directory could not be inspected",
            ));
        }
    }
    let root = std::fs::canonicalize(&requested_path).map_err(|_| {
        safe_error(
            ToolErrorCode::Unavailable,
            "admin project directory could not be canonicalized",
        )
    })?;
    let state = root.join(".cartograph");
    let state_directory_created = match std::fs::symlink_metadata(&state) {
        Ok(metadata) if metadata.file_type().is_symlink() || !metadata.is_dir() => {
            return Err(safe_error(
                ToolErrorCode::InvalidArguments,
                "the .cartograph state entry must be a real directory, not a symlink",
            ));
        }
        Ok(_) => false,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            std::fs::create_dir(&state).map_err(|_| {
                safe_error(
                    ToolErrorCode::Unavailable,
                    "the .cartograph state directory could not be created",
                )
            })?;
            true
        }
        Err(_) => {
            return Err(safe_error(
                ToolErrorCode::Unavailable,
                "the .cartograph state directory could not be inspected",
            ));
        }
    };
    #[cfg(unix)]
    if state_directory_created {
        set_private_state_directory_permissions(&state)?;
    }
    Ok(PreparedAdminProjectRoot {
        root,
        state_directory_created,
    })
}

fn resolve_existing_admin_project_root(
    requested: Option<&str>,
    current_root: &Path,
) -> Result<(PathBuf, bool), ToolError> {
    let requested_path = requested.map_or_else(|| current_root.to_path_buf(), PathBuf::from);
    if !requested_path.is_absolute() {
        return Err(safe_error(
            ToolErrorCode::InvalidArguments,
            "admin init/uninit path must be absolute",
        ));
    }
    let metadata = std::fs::symlink_metadata(&requested_path).map_err(|_| {
        safe_error(
            ToolErrorCode::NotFound,
            "admin project directory was not found",
        )
    })?;
    if metadata.file_type().is_symlink() || !metadata.is_dir() {
        return Err(safe_error(
            ToolErrorCode::InvalidArguments,
            "admin project path must be a real directory, not a symlink",
        ));
    }
    let root = std::fs::canonicalize(requested_path).map_err(|_| {
        safe_error(
            ToolErrorCode::Unavailable,
            "admin project directory could not be canonicalized",
        )
    })?;
    let state = root.join(".cartograph");
    let state_exists = match std::fs::symlink_metadata(&state) {
        Ok(metadata) if metadata.file_type().is_symlink() || !metadata.is_dir() => {
            return Err(safe_error(
                ToolErrorCode::InvalidArguments,
                "the .cartograph state entry must be a real directory, not a symlink",
            ));
        }
        Ok(_) => true,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => false,
        Err(_) => {
            return Err(safe_error(
                ToolErrorCode::Unavailable,
                "the .cartograph state directory could not be inspected",
            ));
        }
    };
    Ok((root, state_exists))
}

fn remove_admin_state_directory(root: &Path) -> Result<bool, ProjectError> {
    let state = root.join(".cartograph");
    let metadata = match std::fs::symlink_metadata(&state) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(false),
        Err(_) => return Err(ProjectError::IndexFailed),
    };
    if metadata.file_type().is_symlink() || !metadata.is_dir() {
        return Err(ProjectError::InvalidOptions);
    }
    std::fs::remove_dir_all(state).map_err(|_| ProjectError::IndexFailed)?;
    Ok(true)
}

#[cfg(unix)]
fn set_private_state_directory_permissions(path: &Path) -> Result<(), ToolError> {
    use std::os::unix::fs::PermissionsExt;

    std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o700)).map_err(|_| {
        safe_error(
            ToolErrorCode::Unavailable,
            "the .cartograph state directory could not be made private",
        )
    })
}

fn parse_admin_database_settings(
    arguments: &Map<String, Value>,
) -> Result<Option<cartograph_config::DatabaseSettings>, ToolError> {
    let provider = optional_bounded_text(
        arguments,
        "databaseProvider",
        ADMIN_DATABASE_OPTION_MAXIMUM_BYTES,
    )?
    .unwrap_or("postgres");
    match provider {
        "postgres" | "postgresql" => {}
        "sqlite" => {
            return Err(safe_error(
                ToolErrorCode::InvalidArguments,
                "SQLite was intentionally removed in Cartograph v2; use PostgreSQL 18 with ParadeDB and pgvector",
            ));
        }
        _ => return Err(invalid_arguments()),
    }
    match optional_bounded_text(
        arguments,
        "databasePgvector",
        ADMIN_DATABASE_OPTION_MAXIMUM_BYTES,
    )? {
        None | Some("auto" | "require") => {}
        Some("off") => {
            return Err(safe_error(
                ToolErrorCode::InvalidArguments,
                "pgvector cannot be disabled in Cartograph v2",
            ));
        }
        Some(_) => return Err(invalid_arguments()),
    }
    let url = optional_bounded_text(arguments, "databaseUrl", ADMIN_DATABASE_URL_MAXIMUM_BYTES)?;
    let has_connection_options = [
        "databaseSchema",
        "databaseMaxConnections",
        "databaseQueryTimeoutMs",
        "databaseConnectionTimeoutSeconds",
        "databaseSsl",
    ]
    .iter()
    .any(|field| arguments.contains_key(*field));
    let Some(url) = url else {
        if has_connection_options {
            return Err(safe_error(
                ToolErrorCode::InvalidArguments,
                "databaseUrl is required when init supplies PostgreSQL connection overrides",
            ));
        }
        return Ok(None);
    };
    let max_connections = optional_bounded_admin_u64(
        arguments,
        "databaseMaxConnections",
        u64::from(ADMIN_DATABASE_MAXIMUM_CONNECTIONS),
    )?;
    let query_timeout = optional_bounded_admin_u64(
        arguments,
        "databaseQueryTimeoutMs",
        ADMIN_QUERY_TIMEOUT_MAXIMUM_MS,
    )?;
    let connection_timeout_seconds = optional_bounded_admin_u64(
        arguments,
        "databaseConnectionTimeoutSeconds",
        ADMIN_CONNECTION_TIMEOUT_MAXIMUM_SECONDS,
    )?;
    let acquire_timeout = connection_timeout_seconds
        .map(|seconds| {
            seconds
                .checked_mul(DATABASE_MILLISECONDS_PER_SECOND)
                .ok_or_else(invalid_arguments)
        })
        .transpose()?;
    let max_connections = max_connections.map(|value| value.to_string());
    let acquire_timeout = acquire_timeout.map(|value| value.to_string());
    let query_timeout = query_timeout.map(|value| value.to_string());
    let mut settings = cartograph_config::DatabaseSettings::parse(
        url,
        max_connections.as_deref(),
        acquire_timeout.as_deref(),
    )
    .and_then(|settings| settings.with_query_timeout_ms(query_timeout.as_deref()))
    .map_err(|_| {
        safe_error(
            ToolErrorCode::InvalidArguments,
            "PostgreSQL initialization settings are invalid",
        )
    })?;
    if let Some(schema) = optional_bounded_text(
        arguments,
        "databaseSchema",
        ADMIN_DATABASE_SCHEMA_MAXIMUM_BYTES,
    )? {
        settings = settings.with_schema(schema).map_err(|_| {
            safe_error(
                ToolErrorCode::InvalidArguments,
                "PostgreSQL initialization schema is invalid",
            )
        })?;
    }
    let require_ssl = optional_bool(arguments, "databaseSsl")?.unwrap_or(false);
    Ok(Some(settings.with_require_ssl(require_ssl)))
}

fn project_llm_error(error: ProjectLlmConfigError) -> ToolError {
    match error {
        ProjectLlmConfigError::InvalidConfig | ProjectLlmConfigError::InvalidTier => {
            invalid_arguments()
        }
        error @ ProjectLlmConfigError::NumericFieldOutOfRange { .. } => {
            safe_error(ToolErrorCode::InvalidArguments, error.to_string())
        }
        ProjectLlmConfigError::CredentialUnavailable => safe_error(
            ToolErrorCode::NotReady,
            "Configured LLM credential environment variable is unavailable",
        ),
        ProjectLlmConfigError::ProjectUnavailable => safe_error(
            ToolErrorCode::NotFound,
            "Cartograph project configuration path is unavailable",
        ),
        ProjectLlmConfigError::ConfigTooLarge => safe_error(
            ToolErrorCode::InvalidArguments,
            "Cartograph project configuration exceeds the one-megabyte limit",
        ),
        ProjectLlmConfigError::ConcurrentModification => safe_error(
            ToolErrorCode::NotReady,
            "Cartograph project configuration changed concurrently; retry the operation",
        ),
        ProjectLlmConfigError::WriteFailed => ToolError::internal(),
    }
}

fn run_mcp_config_io<Output>(
    operation: impl FnOnce() -> Result<Output, ProjectLlmConfigError>,
) -> Result<Output, ProjectLlmConfigError> {
    let Ok(runtime) = tokio::runtime::Handle::try_current() else {
        return operation();
    };
    if !matches!(
        runtime.runtime_flavor(),
        tokio::runtime::RuntimeFlavor::MultiThread
    ) {
        return Err(ProjectLlmConfigError::WriteFailed);
    }
    // Config writes are short and bounded but use synchronous private file
    // locks. `block_in_place` keeps the work attached to this request while
    // Tokio moves unrelated MCP control work off the occupied core worker.
    tokio::task::block_in_place(operation)
}

fn install_models_error(error: InstallModelsError) -> ToolError {
    match error {
        InstallModelsError::InvalidOptions => invalid_arguments(),
        InstallModelsError::DirectoryUnavailable | InstallModelsError::UnsafeTarget => safe_error(
            ToolErrorCode::InvalidArguments,
            "Model directory or target is not a safe regular filesystem location",
        ),
        InstallModelsError::EndpointUnavailable
        | InstallModelsError::BackendRejected
        | InstallModelsError::IdleTimeout => safe_error(
            ToolErrorCode::Unavailable,
            "Recommended model download endpoint is unavailable",
        ),
        InstallModelsError::SizeMismatch | InstallModelsError::ChecksumMismatch => safe_error(
            ToolErrorCode::Unavailable,
            "Downloaded model did not match Cartograph's frozen signed manifest",
        ),
        InstallModelsError::WriteFailed => ToolError::internal(),
    }
}

const fn install_models_project_error(error: InstallModelsError) -> ProjectError {
    match error {
        InstallModelsError::InvalidOptions
        | InstallModelsError::DirectoryUnavailable
        | InstallModelsError::UnsafeTarget => ProjectError::InvalidOptions,
        InstallModelsError::EndpointUnavailable
        | InstallModelsError::BackendRejected
        | InstallModelsError::IdleTimeout
        | InstallModelsError::SizeMismatch
        | InstallModelsError::ChecksumMismatch
        | InstallModelsError::WriteFailed => ProjectError::RetrievalOperationFailed,
    }
}

impl<T> NumericBounds<T> {
    const fn new(minimum: T, default: T, maximum: T) -> Self {
        Self {
            minimum,
            default,
            maximum,
        }
    }
}

/// Product adapter joining the bounded MCP transport to public v2 services.
pub struct CartographMcpHandler {
    runtime: Arc<ProjectRuntime>,
    retrieval: DeterministicRetriever,
    definitions: Vec<ToolDefinition>,
    admin_jobs: AdminJobs,
    session_trace: Arc<SessionTrace>,
    cursor_cache: Arc<CursorCache>,
    project_cache: Arc<ProjectRuntimeCache>,
    managed_database_port: u16,
    defaults: HandlerDefaults,
}

/// Connection-level compatibility defaults applied only when a caller omits
/// the corresponding explicit tool argument.
#[derive(Clone, Copy, Debug, Default)]
pub struct HandlerDefaults {
    pub evidence: HandlerEvidenceDefaults,
    pub execution: HandlerExecutionDefaults,
}

#[derive(Clone, Copy, Debug, Default)]
pub struct HandlerEvidenceDefaults {
    pub allow_stale: bool,
    pub low_tokens: bool,
}

#[derive(Clone, Copy, Debug, Default)]
pub struct HandlerExecutionDefaults {
    pub trace_calls: bool,
    pub read_only: bool,
}

impl CartographMcpHandler {
    pub fn new(runtime: Arc<ProjectRuntime>) -> Result<Self, ToolContractError> {
        let retrieval = DeterministicRetriever::new(runtime.database().clone());
        let project_cache = Arc::new(ProjectRuntimeCache::new(runtime.clone()));
        Ok(Self {
            runtime,
            retrieval,
            definitions: tool_definitions()?,
            admin_jobs: AdminJobs::new(),
            session_trace: Arc::new(SessionTrace {
                state: Mutex::new(SessionTraceState {
                    active_by_project: BTreeMap::new(),
                }),
            }),
            cursor_cache: Arc::new(CursorCache::new()),
            project_cache,
            managed_database_port: cartograph_db::DEFAULT_MANAGED_DATABASE_PORT,
            defaults: HandlerDefaults {
                execution: HandlerExecutionDefaults {
                    trace_calls: true,
                    read_only: false,
                },
                ..HandlerDefaults::default()
            },
        })
    }

    #[must_use]
    pub const fn configured(
        mut self,
        defaults: HandlerDefaults,
        managed_database_port: u16,
    ) -> Self {
        self.defaults = defaults;
        self.managed_database_port = managed_database_port;
        self
    }
}

/// Start native recursive watchers for the default and every lazily routed project.
pub(crate) async fn enable_handler_auto_sync(
    handler: &CartographMcpHandler,
    startup_reconciliation_enabled: bool,
) -> Result<(), AutoSyncError> {
    handler
        .project_cache
        .enable_auto_sync(startup_reconciliation_enabled)
        .await
}

impl CoreTools<'_> {
    async fn auto_sync_status(&self) -> AutoSyncStatus {
        self.project_cache
            .auto_sync_status(self.runtime.project_root_for_host_operations())
            .await
    }

    fn scoped_to(&self, runtime: Arc<ProjectRuntime>) -> CartographMcpHandler {
        CartographMcpHandler {
            retrieval: DeterministicRetriever::new(runtime.database().clone()),
            runtime,
            definitions: self.definitions.clone(),
            admin_jobs: self.admin_jobs.clone(),
            session_trace: self.session_trace.clone(),
            cursor_cache: self.cursor_cache.clone(),
            project_cache: self.project_cache.clone(),
            managed_database_port: self.managed_database_port,
            defaults: self.defaults,
        }
    }

    async fn execute(
        &self,
        call: ToolCall,
        context: ToolCallContext,
    ) -> Result<ToolResult, ToolError> {
        self.execute_with_macro_stack(call, context, Vec::new())
            .await
    }

    async fn execute_with_macro_stack(
        &self,
        mut call: ToolCall,
        context: ToolCallContext,
        macro_stack: Vec<String>,
    ) -> Result<ToolResult, ToolError> {
        if context.should_stop() {
            return Err(safe_error(
                ToolErrorCode::Unavailable,
                "Cartograph request was cancelled before execution",
            ));
        }
        if self.defaults.execution.read_only && !read_only_call_allowed(&self.definitions, &call) {
            return Err(safe_error(
                ToolErrorCode::Unavailable,
                "This mutating tool branch is disabled by the MCP server read-only write gate",
            ));
        }
        self.apply_connection_defaults(&mut call);
        if let Some(project_path) = call.arguments.remove("projectPath") {
            let project_path = project_path.as_str().ok_or_else(invalid_arguments)?;
            let runtime = self
                .project_cache
                .runtime_for(project_path)
                .await
                .map_err(project_route_error)?;
            let scoped = self.scoped_to(runtime);
            return Box::pin(CoreTools(&scoped).execute_with_macro_stack(
                call,
                context,
                macro_stack,
            ))
            .await;
        }
        let trace = if self.defaults.execution.trace_calls {
            TraceQueryTools(self.0).ensure_trace_session().await
        } else {
            None
        };
        let trace_name = call.name.clone();
        let trace_arguments = sanitize_trace_arguments(&call.arguments);
        let started = Instant::now();
        // `dispatch` contains every MCP branch and therefore compiles into a large
        // future. Keep that state machine on the heap so a bounded macro replay
        // does not recursively consume a Tokio worker's native stack.
        let result = Box::pin(self.dispatch(call, context, macro_stack)).await;
        if let Some(trace) = trace {
            TraceQueryTools(self.0)
                .record_trace_call(TraceCallRecord {
                    trace: &trace,
                    tool_name: &trace_name,
                    arguments: trace_arguments,
                    result: &result,
                    duration: started.elapsed(),
                })
                .await;
        }
        result
    }

    fn apply_connection_defaults(&self, call: &mut ToolCall) {
        let Some(definition) = self
            .definitions
            .iter()
            .find(|definition| definition.name() == call.name)
        else {
            return;
        };
        let properties = definition
            .input_schema()
            .get("properties")
            .and_then(Value::as_object);
        if self.defaults.evidence.allow_stale
            && !call.arguments.contains_key("allowStale")
            && properties.is_some_and(|properties| properties.contains_key("allowStale"))
        {
            call.arguments
                .insert("allowStale".to_owned(), Value::Bool(true));
        }
        if self.defaults.evidence.low_tokens
            && !call.arguments.contains_key("lowTokens")
            && properties.is_some_and(|properties| properties.contains_key("lowTokens"))
        {
            call.arguments
                .insert("lowTokens".to_owned(), Value::Bool(true));
        }
    }

    async fn dispatch(
        &self,
        call: ToolCall,
        context: ToolCallContext,
        macro_stack: Vec<String>,
    ) -> Result<ToolResult, ToolError> {
        let cancellation = RequestCancellation::new();
        let group = dispatch_group(&call.name)?;
        let request = DispatchRequest {
            call,
            cancellation: cancellation.signal(),
            context,
            macro_stack,
        };
        match group {
            DispatchGroup::Context => Box::pin(dispatch_context_tools(self, request)).await,
            DispatchGroup::Evidence => Box::pin(dispatch_evidence_tools(self, request)).await,
            DispatchGroup::Workflow => Box::pin(dispatch_workflow_tools(self, request)).await,
            DispatchGroup::Operations => Box::pin(dispatch_operation_tools(self, request)).await,
        }
    }
}

fn dispatch_group(name: &str) -> Result<DispatchGroup, ToolError> {
    match name {
        ASK_TOOL | BLAME_TOOL | CHANGED_SINCE_TOOL | STATUS_TOOL | CONTEXT_TOOL
        | COMPARE_TO_REF_TOOL | DIGEST_TOOL | EXPLORE_TOOL | FIND_TOOL | NODE_TOOL => {
            Ok(DispatchGroup::Context)
        }
        FILES_TOOL | ENTRY_POINTS_TOOL | AT_RANGE_TOOL | GRAPH_TOOL | AFFECTED_TOOL
        | BIOMARKERS_TOOL | NUMERICAL_TOOL | COVERAGE_TOOL | DEAD_CODE_TOOL | DEPS_TOOL
        | HOTSPOTS_TOOL => Ok(DispatchGroup::Evidence),
        HOST_TOOL | HISTORY_TOOL | IMPORTS_TOOL | NOTE_TOOL | PROPOSE_RENAME_TOOL | ROLE_TOOL
        | SESSION_TOOL | SUMMARIES_TOOL | SQL_TOOL | TESTS_FOR_TOOL => Ok(DispatchGroup::Workflow),
        TRACE_TO_CULPRITS_TOOL | VERIFY_TOOL | REVIEW_TOOL | PLAYBOOK_TOOL | ADMIN_TOOL => {
            Ok(DispatchGroup::Operations)
        }
        _ => Err(safe_error(
            ToolErrorCode::NotFound,
            "Cartograph tool is not available",
        )),
    }
}

async fn dispatch_context_tools(
    handler: &CartographMcpHandler,
    request: DispatchRequest,
) -> Result<ToolResult, ToolError> {
    let DispatchRequest {
        call, cancellation, ..
    } = request;
    match call.name.as_str() {
        ASK_TOOL => Box::pin(TraceQueryTools(handler).ask(call.arguments, cancellation)).await,
        BLAME_TOOL => Box::pin(HistoryTools(handler).blame(call.arguments, cancellation)).await,
        CHANGED_SINCE_TOOL => {
            Box::pin(HistoryTools(handler).changed_since(call.arguments, cancellation)).await
        }
        STATUS_TOOL => Box::pin(status_tool(handler, call.arguments, cancellation)).await,
        CONTEXT_TOOL => Box::pin(ContextTools(handler).context(call.arguments, cancellation)).await,
        COMPARE_TO_REF_TOOL => {
            Box::pin(ContextTools(handler).compare_to_ref(call.arguments, cancellation)).await
        }
        DIGEST_TOOL => Box::pin(ContextTools(handler).digest(call.arguments, cancellation)).await,
        EXPLORE_TOOL => Box::pin(ContextTools(handler).explore(call.arguments, cancellation)).await,
        FIND_TOOL => Box::pin(FindTools(handler).find(call.arguments, cancellation)).await,
        NODE_TOOL => Box::pin(node_tool(handler, call.arguments, cancellation)).await,
        _ => Err(ToolError::internal()),
    }
}

async fn dispatch_evidence_tools(
    handler: &CartographMcpHandler,
    request: DispatchRequest,
) -> Result<ToolResult, ToolError> {
    let DispatchRequest {
        call, cancellation, ..
    } = request;
    match call.name.as_str() {
        FILES_TOOL => Box::pin(FilesTools(handler).files(call.arguments, cancellation)).await,
        ENTRY_POINTS_TOOL => {
            Box::pin(FilesTools(handler).entry_points(call.arguments, cancellation)).await
        }
        AT_RANGE_TOOL => Box::pin(FilesTools(handler).at_range(call.arguments, cancellation)).await,
        GRAPH_TOOL => Box::pin(GraphTools(handler).graph(call.arguments, cancellation)).await,
        AFFECTED_TOOL => Box::pin(GraphTools(handler).affected(call.arguments, cancellation)).await,
        BIOMARKERS_TOOL => {
            Box::pin(InsightTools(handler).biomarkers(call.arguments, cancellation)).await
        }
        NUMERICAL_TOOL => {
            Box::pin(InsightTools(handler).numerical(call.arguments, cancellation)).await
        }
        COVERAGE_TOOL => {
            Box::pin(InsightTools(handler).coverage(call.arguments, cancellation)).await
        }
        DEAD_CODE_TOOL => {
            Box::pin(InsightTools(handler).dead_code(call.arguments, cancellation)).await
        }
        DEPS_TOOL => {
            Box::pin(InsightTools(handler).dependencies(call.arguments, cancellation)).await
        }
        HOTSPOTS_TOOL => {
            Box::pin(InsightTools(handler).hotspots(call.arguments, cancellation)).await
        }
        _ => Err(ToolError::internal()),
    }
}

async fn dispatch_workflow_tools(
    handler: &CartographMcpHandler,
    request: DispatchRequest,
) -> Result<ToolResult, ToolError> {
    let DispatchRequest {
        call,
        cancellation,
        context,
        macro_stack,
    } = request;
    match call.name.as_str() {
        HOST_TOOL => Box::pin(ContextTools(handler).host(call.arguments, cancellation)).await,
        HISTORY_TOOL => Box::pin(HistoryTools(handler).history(call.arguments, cancellation)).await,
        IMPORTS_TOOL => Box::pin(InsightTools(handler).imports(call.arguments, cancellation)).await,
        NOTE_TOOL => Box::pin(InsightTools(handler).note(call.arguments, cancellation)).await,
        PROPOSE_RENAME_TOOL => {
            Box::pin(SummaryReviewTools(handler).propose_rename(call.arguments, cancellation)).await
        }
        ROLE_TOOL => Box::pin(InsightTools(handler).role(call.arguments, cancellation)).await,
        SESSION_TOOL => {
            Box::pin(SessionTools(handler).session(SessionRequest {
                arguments: call.arguments,
                cancellation,
                context,
                macro_stack,
            }))
            .await
        }
        SUMMARIES_TOOL => {
            Box::pin(SummaryReviewTools(handler).summaries(call.arguments, cancellation)).await
        }
        SQL_TOOL => Box::pin(SummaryReviewTools(handler).sql(call.arguments, cancellation)).await,
        TESTS_FOR_TOOL => {
            Box::pin(SummaryReviewTools(handler).tests_for(call.arguments, cancellation)).await
        }
        _ => Err(ToolError::internal()),
    }
}

async fn dispatch_operation_tools(
    handler: &CartographMcpHandler,
    request: DispatchRequest,
) -> Result<ToolResult, ToolError> {
    let DispatchRequest {
        call, cancellation, ..
    } = request;
    match call.name.as_str() {
        TRACE_TO_CULPRITS_TOOL => {
            Box::pin(HistoryTools(handler).trace_to_culprits(call.arguments)).await
        }
        VERIFY_TOOL => Box::pin(ContextTools(handler).verify(call.arguments, cancellation)).await,
        REVIEW_TOOL => {
            Box::pin(SummaryReviewTools(handler).review(call.arguments, cancellation)).await
        }
        PLAYBOOK_TOOL => playbook_tool(&call.arguments),
        ADMIN_TOOL => Box::pin(AdminCoreTools(handler).admin(call.arguments)).await,
        _ => Err(ToolError::internal()),
    }
}

const fn admin_dispatch_group(action: AdminAction) -> AdminDispatchGroup {
    if admin_is_lifecycle(action) {
        AdminDispatchGroup::Lifecycle
    } else if admin_is_analysis(action) {
        AdminDispatchGroup::Analysis
    } else if admin_is_models(action) {
        AdminDispatchGroup::Models
    } else {
        panic!("admin action is missing a dispatch group")
    }
}

const fn admin_is_lifecycle(action: AdminAction) -> bool {
    matches!(
        action,
        AdminAction::Init
            | AdminAction::Unlock
            | AdminAction::Index
            | AdminAction::Sync
            | AdminAction::BiomarkersRefresh
            | AdminAction::EmbedOnly
            | AdminAction::Migrate
            | AdminAction::StorageMigrate
            | AdminAction::PruneStore
            | AdminAction::PruneGenerations
    )
}

const fn admin_is_analysis(action: AdminAction) -> bool {
    matches!(
        action,
        AdminAction::EmbeddingAudit
            | AdminAction::EmbeddingCleanup
            | AdminAction::Doctor
            | AdminAction::Embed
            | AdminAction::EmbeddingStatus
            | AdminAction::Classify
            | AdminAction::Summarize
            | AdminAction::Uninit
            | AdminAction::BuildSimilarityEdges
    )
}

const fn admin_is_models(action: AdminAction) -> bool {
    matches!(
        action,
        AdminAction::LlmPlan
            | AdminAction::LlmApply
            | AdminAction::LlmTune
            | AdminAction::InstallModels
            | AdminAction::ScipExport
            | AdminAction::ScipImport
    )
}

async fn admin_dispatch_lifecycle(
    handler: &CartographMcpHandler,
    dispatch: AdminDispatch<'_>,
) -> Result<ToolResult, ToolError> {
    match dispatch.action {
        AdminAction::Init => {
            Box::pin(AdminCoreTools(handler).admin_init(dispatch.action, dispatch.arguments)).await
        }
        AdminAction::Unlock => {
            Box::pin(AdminCoreTools(handler).admin_unlock(dispatch.arguments)).await
        }
        AdminAction::Index | AdminAction::Sync => {
            Box::pin(
                AdminLifecycleTools(handler).start_index_job(dispatch.action, dispatch.arguments),
            )
            .await
        }
        AdminAction::BiomarkersRefresh => {
            Box::pin(AdminCoreTools(handler).admin_biomarkers_refresh(dispatch.arguments)).await
        }
        AdminAction::EmbedOnly => {
            Box::pin(
                AdminLifecycleTools(handler)
                    .start_embed_only_job(dispatch.action, dispatch.arguments),
            )
            .await
        }
        AdminAction::Migrate => {
            Box::pin(AdminCoreTools(handler).admin_migrate(dispatch.arguments)).await
        }
        AdminAction::StorageMigrate => {
            Box::pin(
                AdminLifecycleTools(handler)
                    .start_storage_migrate_job(dispatch.action, dispatch.arguments),
            )
            .await
        }
        AdminAction::PruneStore => {
            Box::pin(
                AdminLifecycleTools(handler)
                    .start_store_prune_job(dispatch.action, dispatch.arguments),
            )
            .await
        }
        AdminAction::PruneGenerations => {
            Box::pin(
                AdminLifecycleTools(handler)
                    .start_generation_prune_job(dispatch.action, dispatch.arguments),
            )
            .await
        }
        _ => Err(ToolError::internal()),
    }
}

async fn admin_dispatch_analysis(
    handler: &CartographMcpHandler,
    dispatch: AdminDispatch<'_>,
) -> Result<ToolResult, ToolError> {
    match dispatch.action {
        AdminAction::EmbeddingAudit => {
            AdminCoreTools(handler)
                .admin_embedding_audit(dispatch.arguments)
                .await
        }
        AdminAction::EmbeddingCleanup => {
            AdminCoreTools(handler)
                .admin_embedding_cleanup(dispatch.arguments)
                .await
        }
        AdminAction::Doctor => {
            AdminCoreTools(handler)
                .admin_doctor(dispatch.arguments)
                .await
        }
        AdminAction::Embed => {
            AdminAnalysisTools(handler)
                .start_embedding_job(dispatch.action, dispatch.arguments)
                .await
        }
        AdminAction::EmbeddingStatus => {
            reject_present(dispatch.arguments, &["force", "workers"])?;
            AdminAnalysisTools(handler)
                .start_embedding_status_job(dispatch.action)
                .await
        }
        AdminAction::Classify => {
            AdminLifecycleTools(handler)
                .start_classify_job(dispatch.action, dispatch.arguments)
                .await
        }
        AdminAction::Summarize => {
            AdminLifecycleTools(handler)
                .start_summarize_job(dispatch.action, dispatch.arguments)
                .await
        }
        AdminAction::Uninit => {
            AdminAnalysisTools(handler)
                .start_uninit_job(dispatch.action, dispatch.arguments)
                .await
        }
        AdminAction::BuildSimilarityEdges => {
            AdminAnalysisTools(handler)
                .start_similarity_materialization_job(dispatch.action, dispatch.arguments)
                .await
        }
        _ => Err(ToolError::internal()),
    }
}

async fn admin_dispatch_models(
    handler: &CartographMcpHandler,
    dispatch: AdminDispatch<'_>,
) -> Result<ToolResult, ToolError> {
    match dispatch.action {
        AdminAction::LlmPlan => {
            AdminCoreTools(handler)
                .admin_llm_plan(dispatch.arguments)
                .await
        }
        AdminAction::LlmApply => AdminCoreTools(handler).admin_llm_apply(dispatch.arguments),
        AdminAction::LlmTune => AdminCoreTools(handler).admin_llm_tune(dispatch.arguments),
        AdminAction::InstallModels => {
            AdminAnalysisTools(handler)
                .start_install_models_job(dispatch.action, dispatch.arguments)
                .await
        }
        AdminAction::ScipExport => {
            AdminLifecycleTools(handler)
                .start_scip_export_job(dispatch.action, dispatch.arguments)
                .await
        }
        AdminAction::ScipImport => {
            AdminLifecycleTools(handler)
                .start_scip_import_job(dispatch.action, dispatch.arguments)
                .await
        }
        _ => Err(ToolError::internal()),
    }
}

fn read_only_call_allowed(definitions: &[ToolDefinition], call: &ToolCall) -> bool {
    if definitions
        .iter()
        .find(|definition| definition.name() == call.name)
        .and_then(ToolDefinition::annotations)
        .is_some_and(|annotations| annotations.read_only_hint == Some(true))
    {
        return true;
    }
    let text = |key: &str| call.arguments.get(key).and_then(Value::as_str);
    match call.name.as_str() {
        COVERAGE_TOOL => {
            let mode = text("mode").unwrap_or(if call.arguments.contains_key("symbol") {
                "symbol"
            } else {
                "ranked"
            });
            matches!(
                mode,
                "symbol" | "ranked" | "stats" | "sources" | "structural"
            )
        }
        HISTORY_TOOL => text("mode") != Some("refresh"),
        NOTE_TOOL => text("action") == Some("list"),
        ROLE_TOOL => {
            !call.arguments.contains_key("symbol") && !call.arguments.contains_key("symbols")
        }
        SESSION_TOOL => matches!(
            text("action"),
            Some("list" | "resume" | "audit" | "usage" | "macro_list")
        ),
        SUMMARIES_TOOL => text("action") == Some("pending"),
        ADMIN_TOOL => {
            matches!(
                text("action"),
                Some("llm-plan" | "embedding-audit" | "embedding-status" | "status")
            ) || (text("action") == Some("doctor")
                && call.arguments.get("fix").and_then(Value::as_bool) != Some(true))
        }
        _ => false,
    }
}

macro_rules! impl_handler_view {
    ($name:ident) => {
        impl std::ops::Deref for $name<'_> {
            type Target = CartographMcpHandler;

            fn deref(&self) -> &Self::Target {
                self.0
            }
        }
    };
}

