fn project_error(error: &ProjectError) -> ToolError {
    match project_error_class(error) {
        ProjectErrorClass::Lookup | ProjectErrorClass::Embedding => project_lookup_error(error),
        ProjectErrorClass::Enrichment | ProjectErrorClass::Operation => {
            project_operation_error(error)
        }
        ProjectErrorClass::Schema => project_actionable_index_error(error),
        ProjectErrorClass::Index if matches!(error, ProjectError::IndexStageFileFailed { .. }) => {
            project_actionable_index_error(error)
        }
        ProjectErrorClass::Index | ProjectErrorClass::General => ToolError::internal(),
    }
}

fn project_lookup_error(error: &ProjectError) -> ToolError {
    match error {
        ProjectError::SymbolNotFound => safe_error(
            ToolErrorCode::NotFound,
            "Symbol was not found in the current generation",
        ),
        ProjectError::FileNotFound => safe_error(
            ToolErrorCode::NotFound,
            "File was not found in the current generation",
        ),
        ProjectError::SourceContextUnavailable => safe_error(
            ToolErrorCode::NotReady,
            "Source context is unavailable; index or synchronize the project first",
        ),
        ProjectError::EmbeddingConfigurationUnavailable => safe_error(
            ToolErrorCode::NotReady,
            "Embedding endpoint and model configuration is unavailable",
        ),
        ProjectError::EmbeddingOperationFailed => safe_error(
            ToolErrorCode::Unavailable,
            "Cartograph semantic embedding operation is unavailable",
        ),
        ProjectError::HnswCreateSharedMemoryUnavailable => safe_error(
            ToolErrorCode::Unavailable,
            "HNSW creation could not allocate shared memory; existing vectors remain resumable after `cartograph db backup` and the confirmed managed database upgrade",
        ),
        _ => ToolError::internal(),
    }
}

fn project_operation_error(error: &ProjectError) -> ToolError {
    match error {
        ProjectError::RetrievalOperationFailed => safe_error(
            ToolErrorCode::Unavailable,
            "Cartograph retrieval operation is unavailable",
        ),
        ProjectError::SourceChangedDuringIndex => safe_error(
            ToolErrorCode::Unavailable,
            "Source changed repeatedly while Cartograph was indexing; retry after the active writes settle",
        ),
        ProjectError::EnrichmentReadFailed => safe_error(
            ToolErrorCode::Unavailable,
            "Cartograph enrichment could not read its current generation data",
        ),
        ProjectError::EnrichmentWriteFailed => safe_error(
            ToolErrorCode::Unavailable,
            "Cartograph enrichment could not persist its generated artifacts",
        ),
        ProjectError::EnrichmentDataInvalid => safe_error(
            ToolErrorCode::Unavailable,
            "Cartograph enrichment encountered invalid stored generation data",
        ),
        ProjectError::InvalidOptions => invalid_arguments(),
        ProjectError::ProjectConfiguration(error) => {
            safe_error(ToolErrorCode::InvalidArguments, error.to_string())
        }
        ProjectError::ScipOverlayInvalid => safe_error(
            ToolErrorCode::InvalidArguments,
            "SCIP artifact is invalid, unsafe, or exceeds its configured bounds",
        ),
        ProjectError::RequestCancelled => safe_error(
            ToolErrorCode::Unavailable,
            "Cartograph request was cancelled",
        ),
        _ => ToolError::internal(),
    }
}

fn project_actionable_index_error(error: &ProjectError) -> ToolError {
    match error {
        ProjectError::IndexStageFileFailed { stage, failure } => safe_error(
            ToolErrorCode::Unavailable,
            format!(
                "Cartograph index failed during {stage}/{failure}; the previous generation remains visible"
            ),
        ),
        ProjectError::SchemaMigrationBlocked {
            database_schema_version,
            required_schema_version,
            pending_migration_version,
        } => ToolError::safe(
            ToolErrorCode::NotReady,
            format!(
                "PostgreSQL schema version {database_schema_version} is below required version {required_schema_version}; pending migration {pending_migration_version} could not be applied; resume the approved database upgrade before retrying"
            ),
        )
        .unwrap_or_else(|_| ToolError::internal()),
        ProjectError::SchemaVersionAhead {
            binary_version,
            database_schema_version,
            supported_schema_version,
        } => ToolError::safe(
            ToolErrorCode::NotReady,
            format!(
                "Cartograph {binary_version} supports schema version {supported_schema_version}, but PostgreSQL is at newer schema version {database_schema_version}; upgrade the binary and repin this MCP registration before retrying"
            ),
        )
        .unwrap_or_else(|_| ToolError::internal()),
        _ => ToolError::internal(),
    }
}

fn project_route_error(error: ProjectRouteError) -> ToolError {
    match error {
        ProjectRouteError::InvalidPath => safe_error(
            ToolErrorCode::InvalidArguments,
            "projectPath must resolve to an existing regular project directory",
        ),
        ProjectRouteError::NotInitialized => safe_error(
            ToolErrorCode::NotFound,
            "No initialized .cartograph project was found at or above projectPath",
        ),
        ProjectRouteError::NotAllowed => safe_error(
            ToolErrorCode::InvalidArguments,
            "projectPath is outside CARTOGRAPH_ALLOWED_PROJECTS",
        ),
        ProjectRouteError::DatabaseUnavailable => safe_error(
            ToolErrorCode::NotReady,
            "The selected project's PostgreSQL data plane is not running or configured",
        ),
        ProjectRouteError::RuntimeUnavailable => safe_error(
            ToolErrorCode::Unavailable,
            "The selected Cartograph project could not be opened",
        ),
    }
}

fn host_inspection_error(error: HostInspectionError) -> ToolError {
    match error {
        HostInspectionError::InvalidOptions => invalid_arguments(),
        HostInspectionError::RootUnavailable => safe_error(
            ToolErrorCode::NotFound,
            "Host discovery root is unavailable",
        ),
        HostInspectionError::Cancelled => {
            safe_error(ToolErrorCode::Unavailable, "Host discovery was cancelled")
        }
        HostInspectionError::WorkerFailed => ToolError::internal(),
    }
}

fn dead_code_judge_error(error: DeadCodeJudgeError) -> ToolError {
    match error {
        DeadCodeJudgeError::InvalidOptions => invalid_arguments(),
        DeadCodeJudgeError::Cancelled => safe_error(
            ToolErrorCode::Unavailable,
            "Dead-code judging was cancelled",
        ),
    }
}

fn dead_code_storage_error(error: StorageError) -> ToolError {
    match error {
        StorageError::StatementTimeout { .. } => safe_error(
            ToolErrorCode::Timeout,
            "dead_code_query_timeout: retry with a smaller maxCandidates bound; the current generation remains available",
        ),
        error => internal_error(error),
    }
}

fn biomarker_refresh_storage_error(error: StorageError) -> ToolError {
    match error {
        StorageError::StatementTimeout { .. } => safe_error(
            ToolErrorCode::Timeout,
            "biomarker_refresh_timeout: retry biomarkers-refresh with a larger bounded databaseQueryTimeoutMs value (legacy timeoutMs is also accepted)",
        ),
        error => internal_error(error),
    }
}

fn safe_error(code: ToolErrorCode, message: impl Into<String>) -> ToolError {
    match ToolError::safe(code, message) {
        Ok(error) => error,
        Err(_) => ToolError::internal(),
    }
}

