    #[tokio::test(flavor = "multi_thread", worker_threads = 1)]
    async fn contended_config_write_does_not_stall_an_unrelated_mcp_ping() {
        let root = tempfile::tempdir().unwrap_or_else(|error| panic!("tempdir failed: {error}"));
        let state = root.path().join(".cartograph");
        std::fs::create_dir(&state).unwrap_or_else(|error| panic!("config state failed: {error}"));
        std::fs::write(state.join("config.json"), r#"{"version":2}"#)
            .unwrap_or_else(|error| panic!("config fixture failed: {error}"));
        let lock = std::fs::OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .truncate(false)
            .open(state.join("config.lock"))
            .unwrap_or_else(|error| panic!("config lock open failed: {error}"));
        File::lock(&lock).unwrap_or_else(|error| panic!("config lock failed: {error}"));

        let started = Arc::new(tokio::sync::Notify::new());
        let handler = ConfigWriteFixtureHandler {
            project: Arc::new(root.path().to_path_buf()),
            started: started.clone(),
        };
        let server = ProtocolServer::new(
            ServerConfig::new(
                ServerMetadata::cartograph(),
                ToolProfile::Full,
                ServerLimits::default(),
            ),
            handler,
        )
        .unwrap_or_else(|error| panic!("config fixture server failed: {error}"));
        let (client, server_stream) = tokio::io::duplex(64 * 1_024);
        let (client_reader, client_writer) = tokio::io::split(client);
        let (server_reader, server_writer) = tokio::io::split(server_stream);
        let server_task =
            tokio::spawn(async move { server.serve(server_reader, server_writer).await });
        let mut reader = BufReader::new(client_reader);
        let mut writer = client_writer;
        let metadata = json!({
            "io.modelcontextprotocol/protocolVersion": MODERN_PROTOCOL_VERSION,
            "io.modelcontextprotocol/clientInfo": {"name": "config-fixture", "version": "1"},
            "io.modelcontextprotocol/clientCapabilities": {}
        });
        protocol_notification(
            &mut writer,
            json!({
                "jsonrpc": "2.0",
                "id": "config-write",
                "method": "tools/call",
                "params": {
                    "_meta": metadata,
                    "name": CONFIG_WRITE_FIXTURE_TOOL,
                    "arguments": {}
                }
            }),
        )
        .await;
        tokio::time::timeout(Duration::from_millis(100), started.notified())
            .await
            .unwrap_or_else(|_| panic!("config writer blocked the only core worker before start"));

        let ping = protocol_request_with_timeout(
            &mut reader,
            &mut writer,
            json!({
                "jsonrpc": "2.0",
                "id": "unrelated-ping",
                "method": "ping",
                "params": {"_meta": metadata}
            }),
            Duration::from_millis(100),
        )
        .await;
        assert_eq!(ping["id"], "unrelated-ping");
        assert_eq!(ping["result"]["resultType"], "complete");

        File::unlock(&lock).unwrap_or_else(|error| panic!("config unlock failed: {error}"));
        let mut line = String::new();
        tokio::time::timeout(Duration::from_secs(1), reader.read_line(&mut line))
            .await
            .unwrap_or_else(|_| panic!("config response timed out"))
            .unwrap_or_else(|error| panic!("config response read failed: {error}"));
        let configured: Value = serde_json::from_str(&line)
            .unwrap_or_else(|error| panic!("config response JSON failed: {error}: {line}"));
        assert_eq!(configured["id"], "config-write");
        assert!(configured.get("error").is_none());

        writer
            .shutdown()
            .await
            .unwrap_or_else(|error| panic!("config protocol shutdown failed: {error}"));
        server_task
            .await
            .unwrap_or_else(|error| panic!("config protocol join failed: {error}"))
            .unwrap_or_else(|error| panic!("config protocol server failed: {error}"));
        let value = std::fs::read_to_string(state.join("config.json"))
            .unwrap_or_else(|error| panic!("config result read failed: {error}"));
        assert!(value.contains("\"maxFileSize\": 8388608"));
    }

    struct NeighborEmbeddingFixture {
        endpoint: String,
        stop: Arc<AtomicBool>,
        requests: Arc<AtomicU64>,
        saw_source_summary: Arc<AtomicBool>,
        saw_target_summary: Arc<AtomicBool>,
        handle: Option<thread::JoinHandle<()>>,
    }

    #[derive(Debug)]
    struct NeighborEmbeddingFixtureReport {
        requests: u64,
        saw_source_summary: bool,
        saw_target_summary: bool,
    }

    impl NeighborEmbeddingFixture {
        fn endpoint(&self) -> &str {
            &self.endpoint
        }

        fn finish(mut self) -> NeighborEmbeddingFixtureReport {
            self.stop.store(true, Ordering::SeqCst);
            if let Some(handle) = self.handle.take() {
                handle
                    .join()
                    .unwrap_or_else(|_| panic!("neighbor embedding fixture panicked"));
            }
            NeighborEmbeddingFixtureReport {
                requests: self.requests.load(Ordering::SeqCst),
                saw_source_summary: self.saw_source_summary.load(Ordering::SeqCst),
                saw_target_summary: self.saw_target_summary.load(Ordering::SeqCst),
            }
        }
    }

    impl Drop for NeighborEmbeddingFixture {
        fn drop(&mut self) {
            self.stop.store(true, Ordering::SeqCst);
            if let Some(handle) = self.handle.take() {
                let _ = handle.join();
            }
        }
    }

    fn policy_call(name: &str, arguments: Value) -> ToolCall {
        ToolCall {
            name: name.to_owned(),
            arguments: match arguments {
                Value::Object(arguments) => arguments,
                Value::Null
                | Value::Bool(_)
                | Value::Number(_)
                | Value::String(_)
                | Value::Array(_) => panic!("policy fixture arguments must be an object"),
            },
        }
    }

    async fn execute_live_tool(
        handler: &CartographMcpHandler,
        name: &str,
        arguments: Value,
    ) -> Value {
        let debug_arguments = arguments.clone();
        let result = CoreTools(handler)
            .execute(
                policy_call(name, arguments),
                ToolCallContext::local(Duration::from_secs(90)),
            )
            .await
            .unwrap_or_else(|error| {
                panic!("live {name} call with {debug_arguments} failed: {error:?}")
            });
        let value = serde_json::to_value(result)
            .unwrap_or_else(|error| panic!("live {name} result serialization failed: {error}"));
        assert!(
            value["content"]
                .as_array()
                .is_some_and(|content| !content.is_empty()),
            "live {name} returned no MCP content: {value}"
        );
        value
    }

    #[test]
    fn read_only_gate_keeps_mixed_reads_and_blocks_every_mutating_branch() {
        let definitions =
            tool_definitions().unwrap_or_else(|error| panic!("tool definitions failed: {error}"));
        for name in [
            COVERAGE_TOOL,
            HISTORY_TOOL,
            NOTE_TOOL,
            ROLE_TOOL,
            SESSION_TOOL,
            SUMMARIES_TOOL,
            ADMIN_TOOL,
        ] {
            assert!(
                definitions
                    .iter()
                    .find(|definition| definition.name() == name)
                    .is_some_and(ToolDefinition::has_read_only_carve_out),
                "{name} lost its read-only advertised carve-out"
            );
        }
        for call in [
            policy_call(COVERAGE_TOOL, json!({"mode": "sources"})),
            policy_call(
                HISTORY_TOOL,
                json!({"mode": "cochanges", "file": "src/a.rs"}),
            ),
            policy_call(NOTE_TOOL, json!({"action": "list"})),
            policy_call(ROLE_TOOL, json!({"role": "util"})),
            policy_call(SESSION_TOOL, json!({"action": "audit"})),
            policy_call(SUMMARIES_TOOL, json!({"action": "pending"})),
            policy_call(ADMIN_TOOL, json!({"action": "llm-plan"})),
            policy_call(ADMIN_TOOL, json!({"action": "doctor", "fix": false})),
        ] {
            assert!(read_only_call_allowed(&definitions, &call), "{}", call.name);
        }
        for call in [
            policy_call(COVERAGE_TOOL, json!({"mode": "load", "reportPath": "x"})),
            policy_call(HISTORY_TOOL, json!({"mode": "refresh"})),
            policy_call(NOTE_TOOL, json!({"action": "add", "text": "x"})),
            policy_call(ROLE_TOOL, json!({"symbol": "x"})),
            policy_call(SESSION_TOOL, json!({"action": "macro_run", "name": "x"})),
            policy_call(SUMMARIES_TOOL, json!({"action": "save", "items": []})),
            policy_call(ADMIN_TOOL, json!({"action": "index"})),
            policy_call(ADMIN_TOOL, json!({"action": "doctor", "fix": true})),
        ] {
            assert!(
                !read_only_call_allowed(&definitions, &call),
                "{}",
                call.name
            );
        }
    }

