    async fn verify_full_index_enrichment(handler: &CartographMcpHandler) {
        AdminLifecycleTools(handler)
            .start_index_job(AdminAction::Index, &Map::new())
            .await
            .unwrap_or_else(|error| panic!("post-index job failed to start: {error}"));
        let started = handler
            .admin_jobs
            .status(None)
            .await
            .unwrap_or_else(|error| panic!("post-index status failed: {error}"));
        let terminal = wait_for_admin_status(
            &handler.admin_jobs,
            started.job_id,
            AdminJobStatus::Succeeded,
        )
        .await;
        let report = terminal
            .report
            .unwrap_or_else(|| panic!("post-index report was missing"));
        assert_eq!(report["report"]["published"], true);
        assert_eq!(report["report"]["publication"]["state"], "published");
        assert_eq!(report["enrichment"]["state"], "complete");
        assert_eq!(
            report["enrichment"]["execution"],
            "tracked_post_publication_admin_job"
        );
        assert_eq!(
            report["enrichment"]["structuralSummaries"]["state"],
            "succeeded"
        );
        assert_eq!(
            report["enrichment"]["initialEmbedding"]["reason"],
            "embedding_not_configured"
        );
    }

    async fn verify_init_index_enrichment(handler: &CartographMcpHandler) {
        AdminCoreTools(handler)
            .admin_init(
                AdminAction::Init,
                &Map::from_iter([("index".to_owned(), json!(true))]),
            )
            .await
            .unwrap_or_else(|error| panic!("init-and-index job failed to start: {error:?}"));
        let init_started = handler
            .admin_jobs
            .status(None)
            .await
            .unwrap_or_else(|error| panic!("init-and-index status failed: {error}"));
        let init_terminal = wait_for_admin_status(
            &handler.admin_jobs,
            init_started.job_id,
            AdminJobStatus::Succeeded,
        )
        .await;
        let init_report = init_terminal
            .report
            .unwrap_or_else(|| panic!("init-and-index report was missing"));
        assert_eq!(init_report["initialization"]["indexRequested"], true);
        assert_eq!(init_report["index"]["published"], false);
        assert_eq!(init_report["index"]["publication"]["state"], "skipped");
        assert_eq!(
            init_report["index"]["publication"]["reason"],
            "unchanged_current_generation"
        );
        assert_eq!(
            init_report["index"]["publication"]["generation_remains_current"],
            true
        );
        assert_eq!(init_report["enrichment"]["state"], "complete");
        assert_eq!(
            init_report["enrichment"]["classification"]["state"],
            "succeeded"
        );
    }

    async fn verify_incremental_sync_enrichment(handler: &CartographMcpHandler) {
        AdminLifecycleTools(handler)
            .start_index_job(AdminAction::Sync, &Map::new())
            .await
            .unwrap_or_else(|error| panic!("sync job failed to start: {error}"));
        let sync_started = handler
            .admin_jobs
            .status(None)
            .await
            .unwrap_or_else(|error| panic!("sync status failed: {error}"));
        let sync_terminal = wait_for_admin_status(
            &handler.admin_jobs,
            sync_started.job_id,
            AdminJobStatus::Succeeded,
        )
        .await;
        let sync_report = sync_terminal
            .report
            .unwrap_or_else(|| panic!("sync report was missing"));
        assert_eq!(sync_report["report"]["published"], true);
        assert_eq!(sync_report["report"]["publication"]["state"], "published");
        assert_eq!(
            sync_report["enrichment"]["state"],
            "deterministic_incremental_complete"
        );
        assert_eq!(
            sync_report["enrichment"]["deepTail"],
            "disabled_for_incremental_sync"
        );
        assert_eq!(
            sync_report["enrichment"]["structuralSummaries"]["state"],
            "succeeded"
        );
        assert_eq!(
            sync_report["enrichment"]["classification"]["state"],
            "succeeded"
        );
        let status = handler
            .runtime
            .status()
            .await
            .unwrap_or_else(|error| panic!("post-sync status failed: {error}"));
        let current_generation = status
            .snapshot
            .and_then(|snapshot| snapshot.current)
            .map_or_else(
                || panic!("post-sync current generation was missing"),
                |current| current.generation_id,
            );
        assert_eq!(
            sync_report["report"]["generation_id"],
            current_generation.as_str()
        );
    }

    async fn verify_generation_prune(handler: &CartographMcpHandler) {
        AdminLifecycleTools(handler)
            .start_generation_prune_job(
                AdminAction::PruneGenerations,
                &Map::from_iter([
                    ("keepSuperseded".to_owned(), json!(0)),
                    ("maximumDeletions".to_owned(), json!(1)),
                    ("maximumCascadeRows".to_owned(), json!(5_200_000)),
                    (
                        "maximumSearchRelationBytes".to_owned(),
                        json!(10_737_418_240_u64),
                    ),
                    ("confirm".to_owned(), json!(true)),
                ]),
            )
            .await
            .unwrap_or_else(|error| panic!("generation prune job failed to start: {error}"));
        let started = handler
            .admin_jobs
            .status(None)
            .await
            .unwrap_or_else(|error| panic!("generation prune status failed: {error}"));
        let terminal = wait_for_admin_status(
            &handler.admin_jobs,
            started.job_id,
            AdminJobStatus::Succeeded,
        )
        .await;
        let report = terminal
            .report
            .unwrap_or_else(|| panic!("generation prune report was missing"));
        assert_eq!(report["current_preserved"], 1);
        assert_eq!(report["superseded_removed"], 1);
        assert_eq!(report["superseded_preserved"], 0);
    }

