    async fn verify_agent_numerical_surfaces(handler: &CartographMcpHandler) {
        let coverage =
            execute_live_tool(handler, NUMERICAL_TOOL, json!({"mode": "coverage"})).await;
        let coverage = &coverage["structuredContent"];
        assert_eq!(coverage["freshness"], "current");
        assert_eq!(coverage["evidence"]["state"], "static_ready");
        assert!(
            coverage["evidence"]["staticEvidence"]["totalSites"]
                .as_u64()
                .is_some_and(|total| total > 0)
        );
        assert_eq!(
            coverage["evidence"]["observationEvidence"]["state"],
            "not_configured"
        );
        assert_eq!(
            coverage["evidence"]["formalEvidence"]["state"],
            "not_configured"
        );

        let sites = execute_live_tool(
            handler,
            NUMERICAL_TOOL,
            json!({
                "mode": "sites",
                "path": "src",
                "operation": "tolerance_comparison",
                "hazard": "absolute_only_tolerance",
                "precision": "f64",
                "evidenceLevel": "heuristic",
                "minConfidence": 0.5,
                "hazardsOnly": true,
                "limit": 10
            }),
        )
        .await;
        let sites = &sites["structuredContent"]["evidence"];
        assert_eq!(sites["sites"]["total"], 1);
        assert_eq!(
            sites["sites"]["sites"][0]["hazard"],
            "absolute_only_tolerance"
        );
        assert_eq!(sites["sites"]["sites"][0]["precision"], "f64");

        for mode in ["explain", "plan"] {
            let result = execute_live_tool(
                handler,
                NUMERICAL_TOOL,
                json!({
                    "mode": mode,
                    "symbol": "stable_equal",
                    "hazardsOnly": true,
                    "limit": 10
                }),
            )
            .await;
            let evidence = &result["structuredContent"]["evidence"];
            assert_eq!(evidence["mode"], mode);
            assert_eq!(evidence["sites"]["total"], 1);
            assert_eq!(evidence["owner"]["qualified_name"], "stable_equal");
            assert!(evidence["affectedTests"].is_object());
            if mode == "plan" {
                assert_eq!(evidence["execution"], "not_performed");
                assert!(
                    evidence["probePlan"]
                        .as_array()
                        .is_some_and(|steps| !steps.is_empty())
                );
            }
        }
    }

    async fn verify_agent_review_and_admin_surfaces(handler: &CartographMcpHandler) {
        for arguments in [
            json!({"mode": "context", "diff": "diff --git a/src/lib.rs b/src/lib.rs\n--- a/src/lib.rs\n+++ b/src/lib.rs\n@@ -7,3 +7,3 @@\n pub fn root(value: i32) -> i32 {\n-    leaf(value)\n+    leaf(value + 1)\n }\n", "pathFilter": "src", "allowStale": true}),
            json!({"mode": "risk", "topN": 20}),
            json!({"mode": "agent-audit", "perDetectorLimit": 10}),
            json!({"mode": "numerical", "topN": 20, "pathFilter": "src"}),
            json!({"mode": "trust", "deep": false, "timeoutMs": 30000}),
        ] {
            execute_live_tool(handler, REVIEW_TOOL, arguments).await;
        }
        let neighbors = CoreTools(handler)
            .execute(
                policy_call(
                    REVIEW_TOOL,
                    json!({"mode": "neighbors", "symbols": ["root"], "k": 5}),
                ),
                ToolCallContext::local(Duration::from_secs(30)),
            )
            .await;
        assert!(
            neighbors.is_ok()
                || neighbors
                    .as_ref()
                    .is_err_and(|error| error.code() == ToolErrorCode::NotReady),
            "neighbor review returned an unexpected failure: {neighbors:?}"
        );
        execute_live_tool(handler, PLAYBOOK_TOOL, json!({})).await;
        let idle_admin_status = CoreTools(handler)
            .execute(
                policy_call(ADMIN_TOOL, json!({"action": "status"})),
                ToolCallContext::local(Duration::from_secs(30)),
            )
            .await;
        assert!(
            idle_admin_status
                .as_ref()
                .is_err_and(|error| error.code() == ToolErrorCode::NotReady),
            "idle admin status must identify the absence of a job: {idle_admin_status:?}"
        );
        execute_live_tool(handler, ADMIN_TOOL, json!({"action": "llm-plan"})).await;
        execute_live_tool(
            handler,
            ADMIN_TOOL,
            json!({"action": "doctor", "fix": false, "skipProjectChecks": true}),
        )
        .await;
    }

    async fn verify_agent_session_and_ask_surfaces(handler: &CartographMcpHandler) {
        execute_live_tool(
            handler,
            SESSION_TOOL,
            json!({"action": "macro_save", "name": "surface-check", "steps": [{"tool": "cartograph_status", "args": {}}, {"tool": "cartograph_playbook", "args": {}}]}),
        )
        .await;
        execute_live_tool(
            handler,
            SESSION_TOOL,
            json!({"action": "macro_run", "name": "surface-check"}),
        )
        .await;
        for action in ["list", "audit", "usage", "macro_list"] {
            execute_live_tool(handler, SESSION_TOOL, json!({"action": action})).await;
        }
        execute_live_tool(
            handler,
            SESSION_TOOL,
            json!({"action": "resume", "label": "agent-surface", "limit": 100}),
        )
        .await;
        execute_live_tool(
            handler,
            SESSION_TOOL,
            json!({"action": "macro_delete", "name": "surface-check"}),
        )
        .await;
        execute_live_tool(
            handler,
            COVERAGE_TOOL,
            json!({"mode": "drop", "source": "agent-surface"}),
        )
        .await;

        let ask = CoreTools(handler)
            .execute(
                policy_call(
                    ASK_TOOL,
                    json!({"question": "What calls leaf?", "retrievalMode": "deterministic"}),
                ),
                ToolCallContext::local(Duration::from_secs(30)),
            )
            .await;
        assert!(
            ask.as_ref()
                .is_err_and(|error| error.code() == ToolErrorCode::NotReady),
            "unconfigured ask must fail closed after evidence retrieval: {ask:?}"
        );
    }

