pub fn leaf(value: i32) -> i32 {
    value + 1
}

pub fn root(value: i32) -> i32 {
    leaf(value)
}

pub fn stable_equal(left: f64, right: f64) -> bool {
    (left - right).abs() < f64::EPSILON
}

